export default function HomepageClientMount({
  content,
}: HomepageClientMountProps) {
  const mountRef = useRef<HTMLDivElement | null>(null);
  const rootRef = useRef<Root | null>(null);

  useEffect(() => {
    const mountNode = mountRef.current;
    if (!mountNode || rootRef.current) {
      return;
    }

    const root = createRoot(mountNode);
    rootRef.current = root;
    root.render(<Homepage content={content} />);

    return () => {
      rootRef.current?.unmount();
      rootRef.current = null;
    };
  }, []);

  return <div ref={mountRef} />;
}

export function clone<T>(value: T, seen = new WeakMap<object, unknown>()): T {
  if (value === null || typeof value !== "object") {
    return value;
  }

  if (seen.has(value)) {
    return seen.get(value) as T;
  }

  if (value instanceof Date) {
    return new Date(value.getTime()) as T;
  }

  if (value instanceof RegExp) {
    return cloneRegExp(value) as T;
  }

  if (value instanceof Map) {
    const cloned = new Map();
    seen.set(value, cloned);
    for (const [key, entryValue] of value) {
      cloned.set(clone(key, seen), clone(entryValue, seen));
    }
    return cloned as T;
  }

  if (value instanceof Set) {
    const cloned = new Set();
    seen.set(value, cloned);
    for (const entry of value) {
      cloned.add(clone(entry, seen));
    }
    return cloned as T;
  }

  if (Array.isArray(value)) {
    const cloned: unknown[] = [];
    seen.set(value, cloned);
    for (const entry of value) {
      cloned.push(clone(entry, seen));
    }
    return cloned as T;
  }

  if (isPlainObject(value)) {
    const cloned: Record<string, unknown> = {};
    seen.set(value, cloned);
    for (const [key, entryValue] of Object.entries(value)) {
      cloned[key] = clone(entryValue, seen);
    }
    return cloned as T;
  }

  return value;
}

